import java.util.*;
import java.io.*;

public class Test {
    int readInt() {
        int result = 0;
        boolean negative = false;
        try {
            int ch;
            boolean started = false;
            while ((ch = System.in.read()) != -1) {
                if (ch == '-') {
                    started = true;
                    negative = true;
                    continue;
                }
                if (ch >= '0' && ch <= '9') {
                    started = true;
                    result = result * 10 + ch - '0';
                } else if (started) {
                    break;
                }
            }
        } catch (IOException e) {
        }
        return negative ? -result : result;
    }

    int r, c;
    Scanner scanner = new Scanner(System.in);
    long[][] C = new long[64][64];
    long bestDist = Long.MAX_VALUE;

    void dfs(long x, long y, int v1, int v2) {
        long dist = Math.abs(x - y);
        if (bestDist <= 1 || dist - C[v1][r] * C[v2][r] >= bestDist) return;
        if (v1 == 0 && v2 == 0) {
            if (dist < bestDist) bestDist = dist;
            return;
        }
        if (v1 > 0) {
            long deltaX = C[v1][r] - C[v1 - 1][r], s2 = C[v2][r];
            dfs(x, y + deltaX * s2, v1 - 1, v2);
        }
        if (v2 > 0) {
            long s1 = C[v1][r], deltaY = C[v2][r] - C[v2 - 1][r];
            dfs(x + s1 * deltaY, y, v1, v2 - 1);
        }
    }

    int[] countA = new int[64], countB = new int[64];
    Map<Long, Long> memo = new TreeMap<>();
    char[] sequence;

    long solve(long x, long y, int v1, int v2) {
        long key = x * 10000 + v1 * 100 + v2;
        Long cached = memo.get(key);
        if (cached != null) return cached;
        long result = 0;
        long d = Math.abs(x - y);
        if (d - C[v1][r] * C[v2][r] > bestDist) {
            memo.put(key, result);
            return result;
        }
        if (v1 == 0 && v2 == 0) return 1;
        char c = sequence[v1 + v2 - 1];
        if (v1 > 0 && c != 'B') {
            long c1 = C[v1][r] - C[v1 - 1][r], s2 = C[v2][r];
            result += solve(x, y + c1 * s2, v1 - 1, v2);
        }
        if (v2 > 0 && c != 'A') {
            long s1 = C[v1][r], c2 = C[v2][r] - C[v2 - 1][r];
            result += solve(x + s1 * c2, y, v1, v2 - 1);
        }
        memo.put(key, result);
        return result;
    }

    void run() {
        r = readInt(); c = readInt(); scanner.nextLine();
        sequence = scanner.nextLine().toCharArray();
        for (int i = 0; i <= 2 * (r + c); i++)
            for (int j = 0; j <= 2 * (r + c); j++) {
                if (j == 0) C[i][j] = 1;
                else if (i == 0) C[i][j] = 0;
                else C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
            }
        int v1 = r + c, v2 = r + c;
        long x = 0, y = 0;
        while (v1 >= r && v2 >= r) {
            if (x > y) {
                long c1 = C[v1][r] - C[v1 - 1][r], s2 = C[v2][r];
                y += c1 * s2;
                v1--;
            } else {
                long s1 = C[v1][r], c2 = C[v2][r] - C[v2 - 1][r];
                x += s1 * c2;
                v2--;
            }
        }
        bestDist = Math.abs(x - y);
        dfs(0, 0, r + c, r + c);
        for (int i = 0; i < 2 * (r + c); i++) {
            countA[i + 1] = countA[i] + (sequence[i] == 'A' ? 1 : 0);
            countB[i + 1] = countB[i] + (sequence[i] == 'B' ? 1 : 0);
        }
        long answer = solve(0, 0, r + c, r + c);
        System.out.println(answer);
    }

    public static void main(String[] args) {
        new Test().run();
    }
}
